def shortest_path(graph, source, target):
    # Initialize the distance dictionary where the distance to the source is 0 and to all others is infinite
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the parent dictionary to keep track of paths
    parents = {node: None for node in graph}
    # Priority queue: the queue contains tuples (distance, node)
    from heapq import heappush, heappop
    queue = [(0, source)]

    while queue:
        current_distance, current_node = heappop(queue)

        # If we found the target, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = parents[current_node]
            path.reverse()
            return (current_distance, path)

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parents[neighbor] = current_node
                heappush(queue, (distance, neighbor))

    # If we exit the loop, it means the target is unreachable
    return (float('inf'), None)

