def shortest_path(graph, source, target):
    import heapq

    # Initialize the priority queue with the source node
    queue = [(0, source, [])]
    visited = set()

    while queue:
        (cost, current_node, path) = heapq.heappop(queue)

        if current_node not in visited:
            visited.add(current_node)

            # If we reached the target, return the path
            if current_node == target:
                return (cost, path + [current_node])

            # Explore neighbors
            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in visited:
                    heapq.heappush(queue, (cost + weight, neighbor, path + [current_node]))

    # If we cannot reach the target, return infinity and None
    return (float("inf"), None)

