def shortest_path(graph, source, target):
    # Initialize the distance dictionary where distance[node] is the shortest
    # distance from the source to node or infinity if unreachable.
    distance = {node: float('inf') for node in graph}

    # The distance to the source node is 0.
    distance[source] = 0

    # Initialize the priority queue with the source node
    from collections import deque
    priority_queue = deque([source])

    # Dictionary to keep track of the previous node in the shortest path
    # from the source to the current node.
    prev = {source: None}

    while priority_queue:
        current = priority_queue.popleft()

        # If we reached the target, construct the path and return
        if current == target:
            path = []
            while current:
                path.append(current)
                current = prev[current]
            return (distance[target], list(reversed(path)))

        # Explore the neighbors
        for neighbor, weight in graph[current]:
            distance_neighbor = distance[current] + weight

            if distance_neighbor < distance[neighbor]:
                # Update the distance and previous node
                distance[neighbor] = distance_neighbor
                prev[neighbor] = current
                priority_queue.append(neighbor)

    # If the target is unreachable, return infinity and None
    return (float('inf'), None)
