def shortest_path(graph, source, target):
    # Initialize the distance dictionary and the predecessor dictionary
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = {node: None for node in graph}

    # Priority queue to manage the nodes to explore
    from collections import deque
    queue = deque([source])

    while queue:
        current = queue.popleft()

        # If we reached the target, we can stop the search
        if current == target:
            break

        # Explore each neighbor of the current node
        for neighbor, weight in graph[current]:
            distance[neighbor] = min(distance[neighbor], distance[current] + weight)
            if distance[neighbor] == distance[current] + weight:
                # If the distance is minimal, update the predecessor
                path[neighbor] = current
                queue.append(neighbor)

    # If we did not reach the target, it means it is unreachable
    if path[target] is None:
        return float('inf'), None
    else:
        # Reconstruct the path
        result_path = [target]
        while result_path[-1] != source:
            result_path.append(path[result_path[-1]])
        result_path.append(source)
        result_path.reverse()
        return distance[target], result_path
